/* ---------- drawing helpers for this lesson (prefixed PE_ so they never clash with engine globals) ---------- */
const PE_F='font-family="Nunito Sans, sans-serif"';
const PE_INK='#18213A', PE_MUT='#5C6577', PE_AX='#ADB5BD';
const PE_SUBMAP=[['Tₒₙ','T','on'],['Iₘₐₓ','I','max'],['Iₘᵢₙ','I','min'],['Vᵢₙ','V','in'],['Pᵢₙ','P','in'],['Vₒ','V','o'],['Vₛ','V','s'],['fₛ','f','s'],['Iₒ','I','o'],['Pₒ','P','o'],['vₒ','v','o'],['iₒ','i','o'],['Tⱼ','T','j'],['Tₐ','T','a'],['θja','θ','ja'],['Pd','P','d']];
const PE_fx=t=>typeof t!=='string'?t:PE_SUBMAP.reduce((q,[u,a,b])=>q.split(u).join(`${a}<tspan baseline-shift="-0.25em" font-size="70%">${b}</tspan>`),t);
const PE_deep=o=>typeof o==='string'?PE_fx(o):Array.isArray(o)?o.map(PE_deep):o;
const PE_T=(x,y,t,o={})=>`<text x="${x}" y="${y}" ${PE_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||PE_INK}"${o.it?' font-style="italic"':''}>${PE_fx(String(t))}</text>`;
const PE_L=(x1,y1,x2,y2,col=PE_MUT,w=2,ex='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const PE_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}"${o.dash?' stroke-dasharray="'+o.dash+'"':''}/>`;
const PE_poly=(P,col,w=4,ex='')=>`<polyline points="${P.map(p=>(+p[0]).toFixed(1)+','+(+p[1]).toFixed(1)).join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round" ${ex}/>`;
const PE_arrow=(x1,y1,x2,y2,col=PE_INK,w=3)=>{const a=Math.atan2(y2-y1,x2-x1),h=14;return PE_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const PE_sub=(a,b)=>`${a}<tspan baseline-shift="-0.25em" font-size="70%">${b}</tspan>`;
const PE_dot=(x,y,col=PE_INK,r=6)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${col}"/>`;
/* a pulse train: baseline yb, height h, pulses [[x on, x off], …] from x0 to x1 */
const PE_pulse=(x0,x1,yb,h,P,col=BLU,w=4)=>{let p=[[x0,yb]];P.forEach(([a,b])=>{p.push([a,yb],[a,yb-h],[b,yb-h],[b,yb])});p.push([x1,yb]);return PE_poly(p,col,w)};
/* evenly spaced pulses: period T px, on-time on px */
const PE_even=(x0,n,T,on)=>Array.from({length:n},(_,i)=>[x0+i*T,x0+i*T+on]);
/* a span bracket above a stretch of axis */
const PE_span=(x1,x2,y,t,col,fs=22)=>PE_L(x1,y,x2,y,col,3)+PE_L(x1,y-8,x1,y+8,col,3)+PE_L(x2,y-8,x2,y+8,col,3)+PE_T((x1+x2)/2,y-12,t,{fs,fw:800,a:'middle',fill:col});
/* circuit symbols */
const PE_res=(x,y1,y2,col=PE_INK,w=3)=>{const m=(y1+y2)/2,a=m-36,s=72/6;let p=[[x,y1],[x,a]];for(let i=0;i<6;i++)p.push([x+(i%2?11:-11),a+s*(i+.5)]);p.push([x,m+36],[x,y2]);return PE_poly(p,col,w)};
const PE_coilV=(x,y1,y2,col=PE_INK,w=3)=>{const m=(y1+y2)/2,a=m-40;let d=`M${x} ${y1}L${x} ${a}`;for(let i=0;i<4;i++)d+=`A10 10 0 0 1 ${x} ${a+20*(i+1)}`;d+=`L${x} ${y2}`;return `<path d="${d}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round"/>`};
const PE_vs=(cx,cy,r=30,col=ORG)=>`<circle cx="${cx}" cy="${cy}" r="${r}" fill="#FFFFFF" stroke="${col}" stroke-width="4"/>`+PE_T(cx,cy-r*.18,'+',{fs:r*.85,fw:800,a:'middle',fill:col})+PE_T(cx,cy+r*.72,'−',{fs:r*.85,fw:800,a:'middle',fill:col});
/* switch between (x1,y) and (x2,y): closed or open */
const PE_sw=(x1,x2,y,closed,col=BLU)=>`<circle cx="${x1}" cy="${y}" r="5" fill="#FFFFFF" stroke="${col}" stroke-width="3"/><circle cx="${x2}" cy="${y}" r="5" fill="#FFFFFF" stroke="${col}" stroke-width="3"/>`+PE_L(x1+4,y-2,closed?x2-4:x2-6,closed?y-2:y-28,col,4);
/* diode pointing up (cathode on top) at x, between y1 (bottom) and y2 (top) */
const PE_diodeUp=(x,y1,y2,col=GRN)=>{const m=(y1+y2)/2;return PE_L(x,y1,x,m+12,PE_INK,3)+PE_L(x,m-12,x,y2,PE_INK,3)+`<polygon points="${x-14},${m+12} ${x+14},${m+12} ${x},${m-10}" fill="${col}"/>`+PE_L(x-14,m-12,x+14,m-12,col,4)};
/* a small chopper circuit: source, switch, diode, R-L load; origin top left, about 470 × 230 */
const PE_chop=(ox,oy,closed)=>`<g transform="translate(${ox} ${oy})">${PE_L(40,20,110,20,PE_INK,3)}${PE_sw(110,170,20,closed)}${PE_L(170,20,380,20,PE_INK,3)}${PE_L(40,220,380,220,PE_INK,3)}${PE_L(40,20,40,90,PE_INK,3)}${PE_L(40,150,40,220,PE_INK,3)}${PE_vs(40,120,30)}${PE_diodeUp(250,220,20)}${PE_dot(250,20)}${PE_dot(250,220)}${PE_res(380,20,110,BLU)}${PE_coilV(380,110,220,BLU)}${PE_T(140,62,'S',{fs:24,fw:800,a:'middle',fill:BLU})}${PE_T(268,128,PE_sub('D','f'),{fs:24,fw:800,fill:GRN})}${PE_T(402,76,'R',{fs:24,fw:800,fill:BLU})}${PE_T(402,172,'L',{fs:24,fw:800,fill:BLU})}</g>`;
/* a heat-sink with fins and a package on it, centre bottom (x,y) */
const PE_sink=(x,y,s=1,col=SLT)=>`<g transform="translate(${x} ${y}) scale(${s})"><rect x="-110" y="-40" width="220" height="40" rx="4" fill="${col}"/>${[-100,-70,-40,-10,20,50,80].map(fx=>`<rect x="${fx}" y="-150" width="18" height="112" rx="3" fill="${col}"/>`).join('')}<rect x="-40" y="-90" width="80" height="50" rx="6" fill="${PE_INK}"/><circle cx="0" cy="-70" r="9" fill="#FFFFFF"/>${[-24,0,24].map(lx=>`<rect x="${lx-4}" y="-40" width="8" height="34" fill="#868E96"/>`).join('')}</g>`;
/* heat wiggles above (x,y) */
const PE_heat=(x,y,col=ORG,n=3)=>Array.from({length:n},(_,i)=>{const xx=x+(i-(n-1)/2)*30;return `<path d="M${xx} ${y} q10 -12 0 -24 q-10 -12 0 -24" fill="none" stroke="${col}" stroke-width="4" stroke-linecap="round"/>`}).join('');
/* power bar: 12 W full scale over w px */
const PE_bar=(x,y,w,h,parts)=>{let s='',xx=x;parts.forEach(([pw,col,lab,lc])=>{const ww=w*pw/12;s+=`<rect x="${xx.toFixed(1)}" y="${y}" width="${ww.toFixed(1)}" height="${h}" fill="${col}"/>`;if(lab)s+=PE_T(xx+ww/2,y+h/2+9,lab,{fs:24,fw:800,a:'middle',fill:lc||'#FFFFFF'});xx+=ww});return s+`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="none" stroke="${PE_INK}" stroke-width="2"/>`};

